                    '👟 装备清单：舒适鞋子 + 儿童小背包（水杯、小零食）+ 湿纸巾',
                    '🖌️ 宝物一·神奇的毛笔：湖笔"大兰蕊"细得像头发丝，是用很多很多羊毛做成的，古代皇帝写字就用它',
                    '✨ 宝物二·会发光的布：古代丝绸五颜六色很漂亮，2000年了颜色还很鲜艳，比我们的衣服还结实',
                    '🎋 宝物三·竹子上的画：竹刻是在竹子上刻出漂亮的图案，上面有七个人在竹林里玩',
                    '💡 互动技巧：用"找一找"游戏引导孩子找三大宝物，每找到一个就夸"你的眼睛真亮！"',
                    '💝 情感连接：握着孩子的手看展品，说"做这些宝物的人好厉害啊，就像你做手工一样认真"',
                    '📸 拍照建议：在三大宝物展柜前各拍一张全家福留念',
                    '🎈 趣味小故事：告诉孩子古代的书法家都用湖笔写字；蚕宝宝吐丝做成美丽的布；竹子可以变成艺术品',
                    '🌟 鼓励时刻：参观结束让孩子说说最喜欢哪个宝物，给予热情的拥抱和鼓励'
