                    '🖌️ 宝物一·湖笔"大兰蕊"：笔锋只有0.5毫米粗，用10万根山羊须做成，是书法家的最爱，体现了工匠精神',
                    '✨ 宝物二·战国"回纹锦"：这是中国最早的提花丝绸，距今2300多年，证明湖州丝绸历史悠久',
                    '🎋 宝物三·明代"竹林七贤图"：竹刻艺术精品，刀法流畅，展现了古代文人的审美情趣',
                    '🎯 参观路线：按照三大宝物顺序参观 - 湖笔展区（30分钟）→ 丝绸展区（40分钟）→ 竹刻展区（30分钟）',
                    '💝 互动引导：引导孩子对比三件宝物的材料（动物毛、蚕丝、竹子）和制作难度',
